import { cacheGet, cacheSet } from "../db";

// ── Types ───────────────────────────────────────────────────────────────────

/** One reported XBRL datapoint, normalized. */
export interface FinPoint {
  value: number;
  end: string; // period end (ISO)
  start?: string; // period start (ISO) for duration concepts
  fy: number;
  fp: string; // "FY" | "Q1".."Q4"
  form: string; // "10-K" | "10-Q" | ...
  accession: string;
  filed: string; // ISO
}

/** Normalized financials consumed by the rules engine. Flow series are annual,
 *  newest-first; balance items are the single most-recent instant value. */
export interface Financials {
  cik: string | null;
  revenue: FinPoint[];
  netIncome: FinPoint[];
  grossProfit: FinPoint[];
  operatingIncome: FinPoint[];
  epsDiluted: FinPoint[];
  operatingCashFlow: FinPoint[];
  capex: FinPoint[];
  assetsCurrent: FinPoint | null;
  liabilitiesCurrent: FinPoint | null;
  stockholdersEquity: FinPoint | null;
  totalDebt: FinPoint | null;
}

interface RawEntry {
  val: number;
  end: string;
  start?: string;
  fy: number;
  fp: string;
  form: string;
  accn: string;
  filed: string;
  frame?: string;
}

interface CompanyFacts {
  cik?: number | string;
  entityName?: string;
  facts?: { "us-gaap"?: Record<string, { units?: Record<string, RawEntry[]> }> };
}

// ── Pure helpers ──────────────────────────────────────────────────────────────

export function padCik(cik: string | number): string {
  return String(cik).replace(/\D/g, "").padStart(10, "0");
}

export function parseCompanyTickers(
  raw: Record<string, { cik_str: number | string; ticker: string; title: string }>,
): Record<string, { cik: string; name: string }> {
  const map: Record<string, { cik: string; name: string }> = {};
  for (const row of Object.values(raw)) {
    if (!row?.ticker) continue;
    map[row.ticker.toUpperCase()] = { cik: padCik(row.cik_str), name: row.title };
  }
  return map;
}

export function buildFilingUrl(cik: string, accession: string): string {
  const cikInt = String(Number(padCik(cik)));
  const noDashes = accession.replace(/-/g, "");
  return `https://www.sec.gov/Archives/edgar/data/${cikInt}/${noDashes}/${accession}-index.htm`;
}

const CONCEPTS = {
  revenue: [
    "Revenues",
    "RevenueFromContractWithCustomerExcludingAssessedTax",
    "RevenueFromContractWithCustomerIncludingAssessedTax",
    "SalesRevenueNet",
  ],
  netIncome: ["NetIncomeLoss", "ProfitLoss"],
  grossProfit: ["GrossProfit"],
  operatingIncome: ["OperatingIncomeLoss"],
  epsDiluted: ["EarningsPerShareDiluted", "EarningsPerShareBasicAndDiluted"],
  operatingCashFlow: [
    "NetCashProvidedByUsedInOperatingActivities",
    "NetCashProvidedByUsedInOperatingActivitiesContinuingOperations",
  ],
  capex: [
    "PaymentsToAcquirePropertyPlantAndEquipment",
    "PaymentsToAcquireProductiveAssets",
  ],
  assetsCurrent: ["AssetsCurrent"],
  liabilitiesCurrent: ["LiabilitiesCurrent"],
  stockholdersEquity: [
    "StockholdersEquity",
    "StockholdersEquityIncludingPortionAttributableToNoncontrollingInterest",
  ],
  longTermDebt: ["LongTermDebtNoncurrent", "LongTermDebt"],
  totalLiabilities: ["Liabilities"],
} as const;

/** Find the first present concept among aliases and return its datapoints,
 *  preferring the requested unit (else the first unit available). */
function entriesFor(
  facts: CompanyFacts,
  names: readonly string[],
  unitPref = "USD",
): RawEntry[] {
  const gaap = facts.facts?.["us-gaap"];
  if (!gaap) return [];
  for (const name of names) {
    const units = gaap[name]?.units;
    if (!units) continue;
    const arr = units[unitPref] ?? Object.values(units)[0];
    if (arr && arr.length) return arr;
  }
  return [];
}

function toPoint(e: RawEntry): FinPoint {
  return {
    value: e.val,
    end: e.end,
    start: e.start,
    fy: e.fy,
    fp: e.fp,
    form: e.form,
    accession: e.accn,
    filed: e.filed,
  };
}

/** Annual (10-K, FY) series, deduped by fiscal year keeping the latest-filed
 *  value (handles restatements), sorted newest period-end first. */
function annualSeries(entries: RawEntry[]): FinPoint[] {
  const annual = entries.filter(
    (e) => e.fp === "FY" && typeof e.form === "string" && e.form.startsWith("10-K"),
  );
  const byFy = new Map<number, RawEntry>();
  for (const e of annual) {
    const prev = byFy.get(e.fy);
    if (!prev || e.filed > prev.filed) byFy.set(e.fy, e);
  }
  return [...byFy.values()]
    .map(toPoint)
    .sort((a, b) => (a.end < b.end ? 1 : a.end > b.end ? -1 : 0));
}

/** Most recent instant value (max period end, tiebreak latest filed). */
function latestInstant(entries: RawEntry[]): FinPoint | null {
  if (!entries.length) return null;
  const best = entries.reduce((acc, e) =>
    e.end > acc.end || (e.end === acc.end && e.filed > acc.filed) ? e : acc,
  );
  return toPoint(best);
}

export function extractFinancials(facts: CompanyFacts): Financials {
  const longTermDebt = latestInstant(entriesFor(facts, CONCEPTS.longTermDebt));
  const totalDebt =
    longTermDebt ?? latestInstant(entriesFor(facts, CONCEPTS.totalLiabilities));

  return {
    cik: facts.cik != null ? padCik(facts.cik) : null,
    revenue: annualSeries(entriesFor(facts, CONCEPTS.revenue)),
    netIncome: annualSeries(entriesFor(facts, CONCEPTS.netIncome)),
    grossProfit: annualSeries(entriesFor(facts, CONCEPTS.grossProfit)),
    operatingIncome: annualSeries(entriesFor(facts, CONCEPTS.operatingIncome)),
    epsDiluted: annualSeries(entriesFor(facts, CONCEPTS.epsDiluted, "USD/shares")),
    operatingCashFlow: annualSeries(entriesFor(facts, CONCEPTS.operatingCashFlow)),
    capex: annualSeries(entriesFor(facts, CONCEPTS.capex)),
    assetsCurrent: latestInstant(entriesFor(facts, CONCEPTS.assetsCurrent)),
    liabilitiesCurrent: latestInstant(entriesFor(facts, CONCEPTS.liabilitiesCurrent)),
    stockholdersEquity: latestInstant(entriesFor(facts, CONCEPTS.stockholdersEquity)),
    totalDebt,
  };
}

// ── Network fetchers (impure, cached) ─────────────────────────────────────────

const UA = `${process.env.EDGAR_CONTACT ?? "advisor-demo contact@example.com"} (advisor-stock-snapshot)`;
const DAY = 24 * 60 * 60 * 1000;

async function edgarFetch(url: string): Promise<any> {
  const res = await fetch(url, {
    headers: { "User-Agent": UA, Accept: "application/json" },
  });
  if (!res.ok) throw new Error(`EDGAR ${res.status} for ${url}`);
  return res.json();
}

/** ticker (any case) -> { cik, name } | null */
export async function lookupCik(
  ticker: string,
): Promise<{ cik: string; name: string } | null> {
  const KEY = "edgar:tickers";
  let map = cacheGet<Record<string, { cik: string; name: string }>>(KEY, DAY);
  if (!map) {
    const raw = await edgarFetch("https://www.sec.gov/files/company_tickers.json");
    map = parseCompanyTickers(raw);
    cacheSet(KEY, map);
  }
  return map[ticker.toUpperCase()] ?? null;
}

export async function fetchCompanyFacts(cik: string): Promise<CompanyFacts> {
  const KEY = `edgar:facts:${padCik(cik)}`;
  const cached = cacheGet<CompanyFacts>(KEY, DAY);
  if (cached) return cached;
  const data = await edgarFetch(
